/* Enforce hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1c2430;
  --color-chassis: #3f5168;
  --color-chassis-dark: #273444;
  --color-chassis-light: #607999;
  --color-screen-bg: #8ba888;
  --color-screen-fg: #142813;
  --color-screen-border: #0e1c0d;
  --color-expired-bg: #c93b3b;
  --color-expired-fg: #fff0f0;
  --color-btn-bg: #dbe4eb;
  --color-btn-text: #19232d;
  --color-btn-shadow: #8f9ea9;
  --color-btn-reset-bg: #df7b7b;
  --color-btn-reset-shadow: #993f3f;
  --color-focus: #ffdd44;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  padding: 24px 16px;
  color: #ffffff;
}

.meter-container {
  width: 100%;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.meter-head {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.meter-cap {
  width: 180px;
  height: 24px;
  background-color: var(--color-chassis-light);
  box-shadow: 
    0 -6px 0 0 var(--color-chassis-dark),
    -6px 0 0 0 var(--color-chassis-dark),
    6px 0 0 0 var(--color-chassis-dark);
}

.meter-casing {
  width: 100%;
  background-color: var(--color-chassis);
  border: 6px solid var(--color-chassis-dark);
  padding: 24px 20px;
  box-shadow: 
    inset 6px 6px 0 var(--color-chassis-light),
    inset -6px -6px 0 var(--color-chassis-dark),
    0 10px 0 rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.screen-bezel {
  background-color: var(--color-chassis-dark);
  padding: 10px;
  box-shadow: inset 4px 4px 0 #0f161e;
}

.screen {
  background-color: var(--color-screen-bg);
  color: var(--color-screen-fg);
  border: 4px solid var(--color-screen-border);
  min-height: 130px;
  padding: 16px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-weight: bold;
  letter-spacing: 1px;
  user-select: none;
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.15);
}

.screen.status-expired {
  background-color: var(--color-expired-bg);
  color: var(--color-expired-fg);
  border-color: #5f1515;
  animation: pulse-border 1.5s infinite alternate;
}

@keyframes pulse-border {
  0% { border-color: #5f1515; }
  100% { border-color: #ffe6e6; }
}

.expired-label {
  font-size: 24px;
  font-weight: 900;
  letter-spacing: 2px;
  line-height: 1.2;
  margin-bottom: 4px;
}

.time-value {
  font-size: 32px;
  font-weight: 900;
  letter-spacing: 3px;
  line-height: 1.2;
}

.status-tag {
  font-size: 14px;
  letter-spacing: 1px;
  margin-top: 6px;
}

.coin-slot-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.coin-slot {
  width: 70px;
  height: 8px;
  background-color: #121922;
  border-bottom: 2px solid var(--color-chassis-light);
}

.coin-slot-label {
  font-size: 13px;
  color: #ced9e3;
  letter-spacing: 1px;
  font-weight: 700;
}

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.pixel-btn {
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  color: var(--color-btn-text);
  background-color: var(--color-btn-bg);
  border: none;
  padding: 14px 8px;
  cursor: pointer;
  box-shadow: 
    -4px 0 0 0 var(--color-chassis-dark),
    4px 0 0 0 var(--color-chassis-dark),
    0 -4px 0 0 var(--color-chassis-dark),
    0 4px 0 0 var(--color-chassis-dark),
    0 6px 0 0 var(--color-btn-shadow);
  transform: translateY(0);
  transition: background-color 0.1s ease, transform 0.05s ease;
}

.btn-reset {
  grid-column: span 2;
  background-color: var(--color-btn-reset-bg);
  box-shadow: 
    -4px 0 0 0 var(--color-chassis-dark),
    4px 0 0 0 var(--color-chassis-dark),
    0 -4px 0 0 var(--color-chassis-dark),
    0 4px 0 0 var(--color-chassis-dark),
    0 6px 0 0 var(--color-btn-reset-shadow);
}

.pixel-btn:hover {
  filter: brightness(1.08);
}

.pixel-btn:focus-visible {
  outline: 4px solid var(--color-focus);
  outline-offset: 3px;
}

.pixel-btn:active {
  transform: translateY(4px);
  box-shadow: 
    -4px 0 0 0 var(--color-chassis-dark),
    4px 0 0 0 var(--color-chassis-dark),
    0 -4px 0 0 var(--color-chassis-dark),
    0 4px 0 0 var(--color-chassis-dark),
    0 2px 0 0 var(--color-btn-shadow);
}

.btn-reset:active {
  box-shadow: 
    -4px 0 0 0 var(--color-chassis-dark),
    4px 0 0 0 var(--color-chassis-dark),
    0 -4px 0 0 var(--color-chassis-dark),
    0 4px 0 0 var(--color-chassis-dark),
    0 2px 0 0 var(--color-btn-reset-shadow);
}

.meter-base-mount {
  width: 140px;
  height: 20px;
  background-color: var(--color-chassis-dark);
}

.meter-pole {
  width: 44px;
  height: 120px;
  background: repeating-linear-gradient(
    90deg,
    #334155 0px,
    #334155 12px,
    #475569 12px,
    #475569 24px,
    #1e293b 24px,
    #1e293b 44px
  );
  border-left: 4px solid #141c24;
  border-right: 4px solid #141c24;
  box-shadow: 0 16px 0 rgba(0, 0, 0, 0.4);
}

document.addEventListener('DOMContentLoaded', () => {
  let remainingSeconds = 0;
  let timerInterval = null;
  let targetTimestamp = null;

  const screenEl = document.getElementById('meter-screen');
  const timeDisplayEl = document.getElementById('time-display');
  const expiredBannerEl = document.getElementById('expired-banner');
  const statusSubtextEl = document.getElementById('status-subtext');

  const add15Btn = document.getElementById('btn-add-15');
  const add60Btn = document.getElementById('btn-add-60');
  const resetBtn = document.getElementById('btn-reset');

  function formatTime(totalSeconds) {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    const mm = String(minutes).padStart(2, '0');
    const ss = String(seconds).padStart(2, '0');
    return `${hours}:${mm}:${ss}`;
  }

  function render() {
    timeDisplayEl.textContent = formatTime(remainingSeconds);

    if (remainingSeconds <= 0 && targetTimestamp !== null) {
      // Expired state
      screenEl.classList.remove('status-idle', 'status-active');
      screenEl.classList.add('status-expired');
      expiredBannerEl.hidden = false;
      timeDisplayEl.hidden = true;
      statusSubtextEl.textContent = 'TIME EXPIRED';
    } else if (remainingSeconds > 0) {
      // Active countdown state
      screenEl.classList.remove('status-idle', 'status-expired');
      screenEl.classList.add('status-active');
      expiredBannerEl.hidden = true;
      timeDisplayEl.hidden = false;
      statusSubtextEl.textContent = 'ZONE ACTIVE';
    } else {
      // Idle cleared/reset state
      screenEl.classList.remove('status-active', 'status-expired');
      screenEl.classList.add('status-idle');
      expiredBannerEl.hidden = true;
      timeDisplayEl.hidden = false;
      statusSubtextEl.textContent = 'INSERT TIME';
    }
  }

  function startTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
    }

    timerInterval = setInterval(() => {
      const now = Date.now();
      const diffSeconds = Math.max(0, Math.ceil((targetTimestamp - now) / 1000));
      remainingSeconds = diffSeconds;
      render();

      if (remainingSeconds <= 0) {
        clearInterval(timerInterval);
        timerInterval = null;
      }
    }, 250);
  }

  function addTime(secondsToAdd) {
    const now = Date.now();
    if (targetTimestamp === null || targetTimestamp < now) {
      targetTimestamp = now + (secondsToAdd * 1000);
    } else {
      targetTimestamp += (secondsToAdd * 1000);
    }
    remainingSeconds = Math.max(0, Math.ceil((targetTimestamp - now) / 1000));
    render();
    startTimer();
  }

  function resetMeter() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    targetTimestamp = null;
    remainingSeconds = 0;
    render();
  }

  add15Btn.addEventListener('click', () => addTime(15 * 60));
  add60Btn.addEventListener('click', () => addTime(60 * 60));
  resetBtn.addEventListener('click', resetMeter);

  render();
});
